1	/**
2	 * UserDashboard — The core product experience after signup.
3	 * Shows: plan status, API keys, usage stats, quick start checklist, billing.
4	 *
5	 * Uses real tRPC procedures:
6	 *   - trpc.apiKeys.list / create / delete / regenerate
7	 *   - trpc.usage.stats
8	 *   - trpc.subscription.current / billingHistory
9	 *   - trpc.stripe.createCheckout / billingPortal
10	 */
11	import { useState } from "react";
12	import { useAuth } from "@/_core/hooks/useAuth";
13	import { trpc } from "@/lib/trpc";
14	import { toast } from "sonner";
15	import { Link } from "wouter";
16	import {
17	  Key, BarChart3, CreditCard, Zap, Copy, Trash2, RefreshCw,
18	  Plus, CheckCircle2, Circle, ExternalLink, ChevronRight,
19	  Activity, Shield, Code2, BookOpen, ArrowUpRight, Eye, EyeOff,
20	  AlertCircle, Loader2
21	} from "lucide-react";
22	import { Button } from "@/components/ui/button";
23	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
24	import { Badge } from "@/components/ui/badge";
25	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
26	import { Progress } from "@/components/ui/progress";
27	import {
28	  Dialog, DialogContent, DialogDescription, DialogFooter,
29	  DialogHeader, DialogTitle, DialogTrigger
30	} from "@/components/ui/dialog";
31	import { Input } from "@/components/ui/input";
32	import { Label } from "@/components/ui/label";
33	
34	const PLAN_COLORS: Record<string, string> = {
35	  free: "bg-slate-100 text-slate-700",
36	  developer: "bg-blue-100 text-blue-700",
37	  team: "bg-violet-100 text-violet-700",
38	  business: "bg-blue-100 text-blue-700",
39	  enterprise: "bg-emerald-100 text-emerald-700",
40	  builder: "bg-blue-100 text-blue-700",
41	  startup: "bg-violet-100 text-violet-700",
42	};
43	
44	const PLAN_LIMITS: Record<string, number> = {
45	  free: 100,
46	  developer: 1000,
47	  team: 10000,
48	  business: 100000,
49	  enterprise: -1,
50	  builder: 15000,
51	  startup: 75000,
52	};
53	
54	function QuickStartChecklist({ hasApiKey, hasUsage }: { hasApiKey: boolean; hasUsage: boolean }) {
55	  const steps = [
56	    { done: true, label: "Create your account", link: null },
57	    { done: hasApiKey, label: "Generate your first API key", link: "#api-keys" },
58	    { done: hasUsage, label: "Make your first governance check", link: "/docs/quickstart" },
59	    { done: false, label: "Integrate with your AI pipeline", link: "/docs" },
60	    { done: false, label: "Set up Slack alerts", link: "/settings/slack" },
61	  ];
62	
63	  const completed = steps.filter(s => s.done).length;
64	
65	  return (
66	    <Card className="border-border/50">
67	      <CardHeader className="pb-3">
68	        <div className="flex items-center justify-between">
69	          <CardTitle className="text-base font-semibold">Getting Started</CardTitle>
70	          <span className="text-xs text-muted-foreground">{completed}/{steps.length} complete</span>
71	        </div>
72	        <Progress value={(completed / steps.length) * 100} className="h-1.5" />
73	      </CardHeader>
74	      <CardContent className="space-y-2">
75	        {steps.map((step, i) => (
76	          <div key={i} className="flex items-center gap-3">
77	            {step.done
78	              ? <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
79	              : <Circle className="h-4 w-4 text-muted-foreground/40 shrink-0" />
80	            }
81	            {step.link && !step.done ? (
82	              <Link href={step.link} className="text-sm text-primary hover:underline flex items-center gap-1">
83	                {step.label} <ChevronRight className="h-3 w-3" />
84	              </Link>
85	            ) : (
86	              <span className={`text-sm ${step.done ? "text-muted-foreground line-through" : "text-foreground"}`}>
87	                {step.label}
88	              </span>
89	            )}
90	          </div>
91	        ))}
92	      </CardContent>
93	    </Card>
94	  );
95	}
96	
97	function ApiKeyCard({ apiKey, onDelete, onRegenerate }: {
98	  apiKey: { id: number; keyPrefix: string; name: string | null; isActive: boolean; createdAt: Date; lastUsedAt: Date | null };
99	  onDelete: (id: number) => void;
100	  onRegenerate: (id: number) => void;
101	}) {
102	  const [showFull, setShowFull] = useState(false);
103	  const displayKey = showFull ? `${apiKey.keyPrefix}${"•".repeat(32)}` : `${apiKey.keyPrefix}••••••••`;
104	
105	  return (
106	    <div className="flex items-center justify-between p-3 rounded-lg border border-border/50 bg-muted/20 hover:bg-muted/40 transition-colors">
107	      <div className="flex items-center gap-3 min-w-0">
108	        <Key className="h-4 w-4 text-muted-foreground shrink-0" />
109	        <div className="min-w-0">
110	          <div className="flex items-center gap-2">
111	            <span className="text-sm font-medium truncate">{apiKey.name || "Unnamed key"}</span>
112	            <Badge variant={apiKey.isActive ? "default" : "secondary"} className="text-xs h-4">
113	              {apiKey.isActive ? "active" : "inactive"}
114	            </Badge>
115	          </div>
116	          <div className="flex items-center gap-2 mt-0.5">
117	            <code className="text-xs text-muted-foreground font-mono">{displayKey}</code>
118	            <button onClick={() => setShowFull(!showFull)} className="text-muted-foreground hover:text-foreground">
119	              {showFull ? <EyeOff className="h-3 w-3" /> : <Eye className="h-3 w-3" />}
120	            </button>
121	          </div>
122	          <p className="text-xs text-muted-foreground mt-0.5">
123	            Created {new Date(apiKey.createdAt).toLocaleDateString()}
124	            {apiKey.lastUsedAt && ` · Last used ${new Date(apiKey.lastUsedAt).toLocaleDateString()}`}
125	          </p>
126	        </div>
127	      </div>
128	      <div className="flex items-center gap-1 shrink-0">
129	        <Button
130	          variant="ghost" size="icon" className="h-7 w-7"
131	          onClick={() => { navigator.clipboard.writeText(apiKey.keyPrefix); toast.success("Key prefix copied"); }}
132	        >
133	          <Copy className="h-3.5 w-3.5" />
134	        </Button>
135	        <Button
136	          variant="ghost" size="icon" className="h-7 w-7"
137	          onClick={() => onRegenerate(apiKey.id)}
138	        >
139	          <RefreshCw className="h-3.5 w-3.5" />
140	        </Button>
141	        <Button
142	          variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive"
143	          onClick={() => onDelete(apiKey.id)}
144	        >
145	          <Trash2 className="h-3.5 w-3.5" />
146	        </Button>
147	      </div>
148	    </div>
149	  );
150	}
151	
152	/**
153	 * ApiKeyRevealDialog — the ONE reliable moment a user can see their full key.
154	 *
155	 * The server only stores a hash, so the plaintext is unrecoverable after this.
156	 * A transient toast was too easy to miss; this is a persistent dialog with a
157	 * copy button, a shown-once warning, and a selectable monospace field.
158	 */
159	function ApiKeyRevealDialog({ apiKey, onClose }: { apiKey: string | null; onClose: () => void }) {
160	  const [copied, setCopied] = useState(false);
161	
162	  const handleCopy = async () => {
163	    if (!apiKey) return;
164	    try {
165	      await navigator.clipboard.writeText(apiKey);
166	      setCopied(true);
167	      toast.success("Copied to clipboard");
168	      setTimeout(() => setCopied(false), 2000);
169	    } catch {
170	      toast.error("Couldn't copy — select the key and copy it manually.");
171	    }
172	  };
173	
174	  const close = () => {
175	    setCopied(false);
176	    onClose();
177	  };
178	
179	  return (
180	    <Dialog open={!!apiKey} onOpenChange={(open) => { if (!open) close(); }}>
181	      <DialogContent onEscapeKeyDown={(e) => e.preventDefault()}>
182	        <DialogHeader>
183	          <DialogTitle>Your new API key</DialogTitle>
184	          <DialogDescription>
185	            Copy your key now and store it somewhere safe.
186	          </DialogDescription>
187	        </DialogHeader>
188	
189	        <div className="flex items-start gap-2 rounded-md border border-blue-200 bg-blue-50 p-3">
190	          <AlertCircle className="h-4 w-4 text-blue-600 mt-0.5 shrink-0" />
191	          <p className="text-xs font-medium text-blue-700">
192	            Save this key now — you won't be able to see it again. We only store a
193	            hashed copy, so it can't be recovered later.
194	          </p>
195	        </div>
196	
197	        <div className="flex items-center gap-2">
198	          <Input
199	            readOnly
200	            aria-label="Your new API key"
201	            value={apiKey ?? ""}
202	            className="font-mono text-xs"
203	            onFocus={(e) => e.currentTarget.select()}
204	          />
205	          <Button
206	            type="button" variant="outline" size="icon"
207	            aria-label="Copy API key"
208	            onClick={handleCopy}
209	          >
210	            {copied ? <CheckCircle2 className="h-4 w-4 text-emerald-500" /> : <Copy className="h-4 w-4" />}
211	          </Button>
212	        </div>
213	
214	        <DialogFooter>
215	          <Button onClick={close}>Done</Button>
216	        </DialogFooter>
217	      </DialogContent>
218	    </Dialog>
219	  );
220	}
221	
222	export default function UserDashboard() {
223	  const { user, loading: authLoading } = useAuth();
224	  const [newKeyName, setNewKeyName] = useState("");
225	  const [createDialogOpen, setCreateDialogOpen] = useState(false);
226	  const [revealedKey, setRevealedKey] = useState<string | null>(null);
227	  const utils = trpc.useUtils();
228	
229	  // Data fetching
230	  const { data: apiKeys, isLoading: keysLoading } = trpc.apiKeys.list.useQuery(undefined, { enabled: !!user });
231	  const { data: usageStats, isLoading: usageLoading } = trpc.usage.stats.useQuery(undefined, { enabled: !!user });
232	  const { data: subscription } = trpc.subscription.current.useQuery(undefined, { enabled: !!user });
233	  const { data: billingHistory, isLoading: billingLoading } = trpc.subscription.billingHistory.useQuery(undefined, { enabled: !!user });
234	
235	  // Mutations
236	  const createKey = trpc.apiKeys.create.useMutation({
237	    onSuccess: (data) => {
238	      utils.apiKeys.list.invalidate();
239	      setCreateDialogOpen(false);
240	      setNewKeyName("");
241	      if (data) {
242	        setRevealedKey(data.key);
243	        toast.success("API key created");
244	      } else {
245	        toast.error("Key created, but we couldn't retrieve it. Please regenerate it to get a usable key.");
246	      }
247	    },
248	    onError: (err) => toast.error(err.message),
249	  });
250	
251	  const deleteKey = trpc.apiKeys.delete.useMutation({
252	    onSuccess: () => { utils.apiKeys.list.invalidate(); toast.success("API key deleted"); },
253	    onError: (err) => toast.error(err.message),
254	  });
255	
256	  const regenerateKey = trpc.apiKeys.regenerate.useMutation({
257	    onSuccess: (data) => {
258	      utils.apiKeys.list.invalidate();
259	      if (data) {
260	        setRevealedKey(data.key);
261	        toast.success("API key regenerated");
262	      } else {
263	        toast.error("Couldn't regenerate the key. Please try again.");
264	      }
265	    },
266	    onError: (err) => toast.error(err.message),
267	  });
268	
269	  const _createCheckout = trpc.stripe.createGravitoCheckout.useMutation({
270	    onSuccess: (data) => {
271	      if (data.url) window.open(data.url, "_blank");
272	    },
273	    onError: (err) => toast.error(err.message),
274	  });
275	
276	  const openBillingPortal = trpc.stripe.createGravitoPortalSession.useMutation({
277	    onSuccess: (data) => {
278	      if (data.url) window.open(data.url, "_blank");
279	    },
280	    onError: (err) => toast.error(err.message),
281	  });
282	
283	  if (authLoading) {
284	    return (
285	      <div className="flex items-center justify-center min-h-screen">
286	        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
287	      </div>
288	    );
289	  }
290	
291	  if (!user) {
292	    return (
293	      <div className="flex items-center justify-center min-h-screen">
294	        <div className="text-center space-y-4">
295	          <AlertCircle className="h-10 w-10 text-muted-foreground mx-auto" />
296	          <p className="text-muted-foreground">Please log in to access your dashboard.</p>
297	          <Button asChild><Link href="/login">Log in</Link></Button>
298	        </div>
299	      </div>
300	    );
301	  }
302	
303	  const plan = subscription?.plan || "free";
304	  const planLimit = PLAN_LIMITS[plan] ?? 100;
305	  const usageTotal = usageStats?.total ?? 0;
306	  const usagePct = planLimit > 0 ? Math.min(100, Math.round((usageTotal / planLimit) * 100)) : 0;
307	  const hasApiKey = (apiKeys?.length ?? 0) > 0;
308	  const hasUsage = usageTotal > 0;
309	
310	  return (
311	    <div className="min-h-screen bg-background">
312	      {/* Header */}
313	      <div className="border-b border-border/50 bg-card/50">
314	        <div className="max-w-6xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
315	          <div className="flex items-center gap-3">
316	            <Link href="/" className="flex items-center gap-2 text-foreground hover:text-primary transition-colors">
317	              <Shield className="h-5 w-5 text-primary" />
318	              <span className="font-semibold text-sm">Gravito</span>
319	            </Link>
320	            <span className="text-muted-foreground/40">/</span>
321	            <span className="text-sm text-muted-foreground">Dashboard</span>
322	          </div>
323	          <div className="flex items-center gap-3">
324	            <Badge className={`text-xs ${PLAN_COLORS[plan] || "bg-slate-100 text-slate-700"}`}>
325	              {plan.charAt(0).toUpperCase() + plan.slice(1)} plan
326	            </Badge>
327	            <span className="text-sm text-muted-foreground hidden sm:block">{user.name || user.email}</span>
328	          </div>
329	        </div>
330	      </div>
331	
332	      <div className="max-w-6xl mx-auto px-4 sm:px-6 py-8 space-y-6">
333	        {/* Welcome + Stats Row */}
334	        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
335	          <Card className="border-border/50">
336	            <CardContent className="pt-4">
337	              <div className="flex items-center gap-2 text-muted-foreground mb-1">
338	                <Activity className="h-4 w-4" />
339	                <span className="text-xs font-medium uppercase tracking-wide">Checks this month</span>
340	              </div>
341	              {usageLoading ? (
342	                <div className="h-8 w-24 bg-muted animate-pulse rounded" />
343	              ) : (
344	                <div className="flex items-end gap-2">
345	                  <span className="text-2xl font-bold">{usageTotal.toLocaleString()}</span>
346	                  {planLimit > 0 && (
347	                    <span className="text-xs text-muted-foreground mb-1">/ {planLimit.toLocaleString()}</span>
348	                  )}
349	                </div>
350	              )}
351	              {planLimit > 0 && !usageLoading && (
352	                <Progress value={usagePct} className="h-1 mt-2" />
353	              )}
354	            </CardContent>
355	          </Card>
356	
357	          <Card className="border-border/50">
358	            <CardContent className="pt-4">
359	              <div className="flex items-center gap-2 text-muted-foreground mb-1">
360	                <Shield className="h-4 w-4" />
361	                <span className="text-xs font-medium uppercase tracking-wide">Gates blocked</span>
362	              </div>
363	              {usageLoading ? (
364	                <div className="h-8 w-16 bg-muted animate-pulse rounded" />
365	              ) : (
366	                <span className="text-2xl font-bold">{(usageStats?.gatesBlocked ?? 0).toLocaleString()}</span>
367	              )}
368	              <p className="text-xs text-muted-foreground mt-1">Policy violations caught</p>
369	            </CardContent>
370	          </Card>
371	
372	          <Card className="border-border/50">
373	            <CardContent className="pt-4">
374	              <div className="flex items-center gap-2 text-muted-foreground mb-1">
375	                <BarChart3 className="h-4 w-4" />
376	                <span className="text-xs font-medium uppercase tracking-wide">Avg score</span>
377	              </div>
378	              {usageLoading ? (
379	                <div className="h-8 w-16 bg-muted animate-pulse rounded" />
380	              ) : (
381	                <span className="text-2xl font-bold">
382	                  {usageStats?.averageScore ? `${Math.round(usageStats.averageScore * 100)}%` : "—"}
383	                </span>
384	              )}
385	              <p className="text-xs text-muted-foreground mt-1">Governance quality score</p>
386	            </CardContent>
387	          </Card>
388	
389	          <Card className="border-border/50">
390	            <CardContent className="pt-4">
391	              <div className="flex items-center gap-2 text-muted-foreground mb-1">
392	                <Key className="h-4 w-4" />
393	                <span className="text-xs font-medium uppercase tracking-wide">API keys</span>
394	              </div>
395	              {keysLoading ? (
396	                <div className="h-8 w-10 bg-muted animate-pulse rounded" />
397	              ) : (
398	                <span className="text-2xl font-bold">{apiKeys?.length ?? 0}</span>
399	              )}
400	              <p className="text-xs text-muted-foreground mt-1">Active integrations</p>
401	            </CardContent>
402	          </Card>
403	        </div>
404	
405	        {/* Main Content */}
406	        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
407	          {/* Left: Tabs */}
408	          <div className="lg:col-span-2">
409	            <Tabs defaultValue="api-keys" id="api-keys">
410	              <TabsList className="grid grid-cols-3 w-full">
411	                <TabsTrigger value="api-keys" className="gap-1.5">
412	                  <Key className="h-3.5 w-3.5" /> API Keys
413	                </TabsTrigger>
414	                <TabsTrigger value="usage" className="gap-1.5">
415	                  <BarChart3 className="h-3.5 w-3.5" /> Usage
416	                </TabsTrigger>
417	                <TabsTrigger value="billing" className="gap-1.5">
418	                  <CreditCard className="h-3.5 w-3.5" /> Billing
419	                </TabsTrigger>
420	              </TabsList>
421	
422	              {/* API Keys Tab */}
423	              <TabsContent value="api-keys" className="mt-4 space-y-3">
424	                <div className="flex items-center justify-between">
425	                  <div>
426	                    <h3 className="text-sm font-semibold">API Keys</h3>
427	                    <p className="text-xs text-muted-foreground">Use these keys to authenticate requests to the Gravito API.</p>
428	                  </div>
429	                  <Dialog open={createDialogOpen} onOpenChange={setCreateDialogOpen}>
430	                    <DialogTrigger asChild>
431	                      <Button size="sm" className="gap-1.5">
432	                        <Plus className="h-3.5 w-3.5" /> New key
433	                      </Button>
434	                    </DialogTrigger>
435	                    <DialogContent>
436	                      <DialogHeader>
437	                        <DialogTitle>Create API key</DialogTitle>
438	                        <DialogDescription>
439	                          Give your key a name to identify where it's used (e.g. "Production", "CI/CD").
440	                        </DialogDescription>
441	                      </DialogHeader>
442	                      <div className="space-y-2 py-2">
443	                        <Label htmlFor="key-name">Key name (optional)</Label>
444	                        <Input
445	                          aria-label="e.g. Production" id="key-name"
446	                          placeholder="e.g. Production"
447	                          value={newKeyName}
448	                          onChange={(e) => setNewKeyName(e.target.value)}
449	                        />
450	                      </div>
451	                      <DialogFooter>
452	                        <Button variant="outline" onClick={() => setCreateDialogOpen(false)}>Cancel</Button>
453	                        <Button
454	                          onClick={() => createKey.mutate({ name: newKeyName || undefined })}
455	                          disabled={createKey.isPending}
456	                        >
457	                          {createKey.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
458	                          Create key
459	                        </Button>
460	                      </DialogFooter>
461	                    </DialogContent>
462	                  </Dialog>
463	                </div>
464	
465	                {keysLoading ? (
466	                  <div className="space-y-2">
467	                    {[1, 2].map(i => <div key={i} className="h-16 bg-muted animate-pulse rounded-lg" />)}
468	                  </div>
469	                ) : apiKeys && apiKeys.length > 0 ? (
470	                  <div className="space-y-2">
471	                    {apiKeys.map((key) => (
472	                      <ApiKeyCard
473	                        key={key.id}
474	                        apiKey={key}
475	                        onDelete={(id) => deleteKey.mutate({ keyId: id })}
476	                        onRegenerate={(id) => regenerateKey.mutate({ keyId: id })}
477	                      />
478	                    ))}
479	                  </div>
480	                ) : (
481	                  <div className="text-center py-10 border border-dashed border-border rounded-lg">
482	                    <Key className="h-8 w-8 text-muted-foreground/40 mx-auto mb-3" />
483	                    <p className="text-sm font-medium">No API keys yet</p>
484	                    <p className="text-xs text-muted-foreground mt-1 mb-4">Create your first key to start using the Gravito API.</p>
485	                    <Button size="sm" onClick={() => setCreateDialogOpen(true)} className="gap-1.5">
486	                      <Plus className="h-3.5 w-3.5" /> Create API key
487	                    </Button>
488	                  </div>
489	                )}
490	
491	                <div className="rounded-lg bg-muted/30 border border-border/40 p-3 mt-2">
492	                  <p className="text-xs text-muted-foreground font-medium mb-1">Quick start</p>
493	                  <code className="text-xs font-mono text-foreground/80 block">
494	                    curl -H "Authorization: Bearer YOUR_KEY" \<br />
495	                    &nbsp;&nbsp;https://api.Gravito.ai/v1/check
496	                  </code>
497	                  <Link href="/docs/quickstart" className="text-xs text-primary hover:underline flex items-center gap-1 mt-2">
498	                    View full docs <ExternalLink className="h-3 w-3" />
499	                  </Link>
500	                </div>
501	              </TabsContent>
502	
503	              {/* Usage Tab */}
504	              <TabsContent value="usage" className="mt-4 space-y-4">
505	                <div>
506	                  <h3 className="text-sm font-semibold">Usage this month</h3>
507	                  <p className="text-xs text-muted-foreground">
508	                    {planLimit > 0
509	                      ? `${usageTotal.toLocaleString()} of ${planLimit.toLocaleString()} checks used`
510	                      : `${usageTotal.toLocaleString()} checks used (unlimited)`}
511	                  </p>
512	                </div>
513	
514	                {usageLoading ? (
515	                  <div className="space-y-3">
516	                    {[1, 2, 3].map(i => <div key={i} className="h-12 bg-muted animate-pulse rounded-lg" />)}
517	                  </div>
518	                ) : (
519	                  <div className="space-y-3">
520	                    {planLimit > 0 && (
521	                      <div className="space-y-1.5">
522	                        <div className="flex justify-between text-xs text-muted-foreground">
523	                          <span>Checks used</span>
