export async function createApiKey(userId: number, name?: string): Promise<{ key: string; prefix: string } | null> {
  const { key, hash, prefix } = generateApiKey();

  const { error } = await supabase
    .from('api_keys')
    .insert({
      user_id: userId,
      key_hash: hash,
      key_prefix: prefix,
      name: name || 'Default Key',
      is_active: true,
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error creating API key');
    return null;
  }
  return { key, prefix };
}

export async function getApiKeysByUserId(userId: number): Promise<Partial<ApiKey>[]> {
  const { data, error } = await supabase
    .from('api_keys')
    .select('id, key_prefix, name, is_active, last_used_at, created_at')
    .eq('user_id', userId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting API keys');
    return [];
  }
  return data || [];
}

export async function validateApiKey(key: string): Promise<ApiKey | null> {
  const hash = hashApiKey(key);

  const { data, error } = await supabase
    .from('api_keys')
    .select('*')
    .eq('key_hash', hash)
    .eq('is_active', true)
    .single();

  if (error) {
    return null;
  }

  // Update last used
  await supabase
    .from('api_keys')
    .update({ last_used_at: new Date().toISOString() })
    .eq('id', data.id);

  return data;
}

