const [, setLocation] = useLocation();
const [currentStep, setCurrentStep] = useState(0);
const [copiedKey, setCopiedKey] = useState(false);
const [copiedSnippet, setCopiedSnippet] = useState(false);

const { data: subscriptionData } = trpc.subscription.current.useQuery(undefined, { enabled: !!user });
const { data: apiKeysData, refetch: refetchKeys } = trpc.apiKeys.list.useQuery(undefined, { enabled: !!user });

const createApiKey = trpc.apiKeys.create.useMutation({
  onSuccess: () => { refetchKeys(); toast.success("API key created!"); setCurrentStep(2); },
  onError: (err) => toast.error(err.message),
});

const createCheckout = trpc.stripe.createGravitoCheckout.useMutation({
  onSuccess: (data) => { if (data.url) window.open(data.url, "_blank"); },
  onError: (err) => toast.error(err.message),
});

if (isLoading) return (
  <div className="min-h-screen flex items-center justify-center bg-background">
    <div className="animate-spin h-8 w-8 border-2 border-primary border-t-transparent rounded-full" />
  </div>
);

if (!user) { window.location.href = getLoginUrl(); return null; }

const hasPlan = !!subscriptionData?.plan;
const firstKey = apiKeysData?.[0];
const hasKey = !!firstKey;
const completedSteps = new Set<number>();
if (hasPlan) completedSteps.add(0);
if (hasKey) { completedSteps.add(0); completedSteps.add(1); }

const copyToClipboard = (text: string, type: "key" | "snippet") => {
  navigator.clipboard.writeText(text);
  if (type === "key") { setCopiedKey(true); setTimeout(() => setCopiedKey(false), 2000); }
  else { setCopiedSnippet(true); setTimeout(() => setCopiedSnippet(false), 2000); }
  toast.success("Copied!");
};

