1	#!/usr/bin/env node
2	// Stop-event adapter: decide whether this turn may end.
3	//
4	// Exit 0 = allow the stop. Exit 2 = REFUSE, with stderr shown to the model.
5	// It shares ONE ruleset with the audit path (concession-gate.mjs); there is no
6	// second copy of the stopping rule that could drift from the first.
7	import fs from "node:fs";
8	import { isConcession } from "./concession-gate.mjs";
9	import { enumerateCapability } from "./capability-map.mjs";
10	import { continuationDecision, TERMINAL_CONDITIONS as TERMINAL } from "./continuation.mjs";
11	
12	let ev = {};
13	try { ev = JSON.parse(fs.readFileSync(0, "utf8")); } catch { process.exit(0); }
14	
15	// A recorded exhaustion artifact for THIS turn is what satisfies the gate.
16	const EVIDENCE = `${process.env.CLAUDE_PROJECT_DIR || "."}/build-os/motion/exhaustion/current.json`;
17	
18	let lastAssistant = "";
19	try {
20	  const lines = fs.readFileSync(ev.transcript_path, "utf8").split("\n").filter(Boolean);
21	  for (let i = lines.length - 1; i >= 0; i--) {
22	    const m = JSON.parse(lines[i]);
23	    if (m?.message?.role === "assistant") {
24	      lastAssistant = (m.message.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n");
25	      break;
26	    }
27	  }
28	} catch { process.exit(0); }
29	
30	// CONTINUATION IS CHECKED FIRST, and it applies whether or not the turn
31	// concedes. The observed defect was a turn that conceded NOTHING - it simply
32	// finished a task and stopped - so a stop gate that only inspects concessions
33	// would have allowed it.
